'int cc_run(const struct cc_ins *ir,size_t n,uint32_t x,uint32_t *out){uint32_t s[64];size_t i,sp=0;unsigned peak;if(!cc_validate(ir,n,&peak))return 0;for(i=0;i<n;++i){unsigned op=ir[i].op;if(op==1)s[sp++]=ir[i].value;else if(op==2)s[sp++]=x;else if(op==3||op==4){uint32_t b=s[--sp],a=s[--sp],v;if(!cc_binary(op,a,b,&v))return 0;s[sp++]=v;}else{*out=B06_MUTATION==4?0:s[0];return 1;}}return 0;}',
