'int cc_validate(const struct cc_ins *ir, size_t n, unsigned *peak);',
'int cc_validate(const struct cc_ins *ir,size_t n,unsigned *peak){size_t i;unsigned sp=0,max=0;if(n==0||n>128)return 0;for(i=0;i<n;++i){unsigned op=ir[i].op;if(op==1||op==2){if((op==1&&ir[i].value>65535)||sp==64)return 0;++sp;if(sp>max)max=sp;}else if(op==3||op==4){if(sp<2)return 0;--sp;}else if(op==5){if(sp!=1||(i+1!=n&&B06_MUTATION!=5))return 0;*peak=max;return 1;}else return 0;}return 0;}',
